define({"topics":[{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_3.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e17310","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_2.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e17414","topics":[]}]});